content.text:
The main fault is ts-travel-plan-service's outbound HTTP GET calls to ts-train-service's `/trains/byName`, which are held about 600 ms while the train server spans stay at about 4 ms. Its other outbound POSTs stay normal. I'm classing this as `http_slow` because it is path-specific at the caller and leaves the callee and the connection's other traffic alone. The "network_delay" alternative is less likely, since the hubble counters show no drops or retransmits on that connection.

```json
{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "http_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, c.service_name callee, c.span_name, COUNT(*) n, ROUND(quantile_cont(par.duration,0.5)/1e6,1) caller_gap_p50_ms, ROUND(quantile_cont(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces par JOIN abnormal_traces c ON c.parent_span_id=par.span_id AND c.trace_id=par.trace_id WHERE par.service_name='ts-travel-plan-service' AND par.attr_span_kind='Client' AND par.span_name='GET' GROUP BY 1,2,3 UNION ALL SELECT 'norm', c.service_name, c.span_name, COUNT(*), ROUND(quantile_cont(par.duration,0.5)/1e6,1), ROUND(quantile_cont(c.duration,0.5)/1e6,1) FROM normal_traces par JOIN normal_traces c ON c.parent_span_id=par.span_id AND c.trace_id=par.trace_id WHERE par.service_name='ts-travel-plan-service' AND par.attr_span_kind='Client' AND par.span_name='GET' GROUP BY 1,2,3", "claim": "Travel-plan's outbound GET to train-service byName takes about 613ms at the caller while the train server span stays about 3.5ms."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Client' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, COUNT(*), ROUND(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Client' GROUP BY 1,2,3,4", "claim": "Travel-plan GET client p95 rose from about 8ms to 617ms, while its POST client calls stay normal."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, COUNT(*) n, ROUND(quantile_cont(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2,3 UNION ALL SELECT 'norm', service_name, span_name, COUNT(*), ROUND(quantile_cont(duration,0.95)/1e6,1) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2,3", "claim": "User-facing travelPlan requests at ui-dashboard slowed to p95 of about 3.3-3.5s from about 1s."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT 'abn' p, par.service_name caller, par.span_name, COUNT(*) n, ROUND(quantile_cont(par.duration,0.95)/1e6,1) p95_ms FROM abnormal_traces par WHERE par.service_name='ts-ui-dashboard' AND par.span_name LIKE 'POST /api/v1/travelplanservice%' GROUP BY 1,2,3", "claim": "ui-dashboard travelPlan requests inherit travel-plan's slow outbound GET, rising to p95 about 3.5s."}]}
  ]
}
```

